Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method ProcessHttpsRequest with token: " _ pRequest.accessToken)

	// set dataStr = {"query":"mutation {\n  createTransaction(\n    transactionInput: {\n      tranId: 154\n      tranDate: \"2019/10/25\"\n      tranPostingDate: \"2019/10/25\"\n      tranType: \"P\"\n      tranCodeId: 222\n      tranCodeText: \"VD\"\n      tranDesc: \"A desc\"\n      tranQuantity: 1\n      tranAmountExt: 111.11\n      tranAmountUnit: \"US\"\n      patientLocation: \"\"\n      performedBy: \"XXX\"\n      enteredBy: \"YYY\"\n    }\n  )\n}"}
	// set dataStr = {"query":"mutation {  createTransaction(    transactionInput: {      tranId: 154      tranDate: \"2019/10/25\"      tranPostingDate: \"2019/10/25\"      tranType: \"P\"      tranCodeId: 222      tranCodeText: \"VD\"      tranDesc: \"A desc\"      tranQuantity: 1      tranAmountExt: 111.11      tranAmountUnit: \"US\"      patientLocation: \"\"      performedBy: \"XXX\"      enteredBy: \"YYY\"    }  )}"}
	// Godd recon
	// set dataStr = {"query":"mutation createReconciliation($recInp: ReconciliationInput!) { createReconciliation(reconciliationInput: $recInp)  }","variables":{"recInp":{"sentDate": "2019/11/25","transactionsCount": 10.0,"transactionsAmount": 200}}}

	// Good Trans
	// set dataStr = {"query": "mutation createTransaction($recInp: TransactionInput!)    {        createTransaction(transactionInput: $recInp)           }","variables": {	"recInp":	{	"tranId": 12345,    "tranDate": "2019/10/25",     	 "tranPostingDate": "2019/10/25",      	 "tranType": "P",    	 "tranCodeId": 222,     	 "tranCodeText": "VD",     	 "tranDesc": "A desc",      	 "tranQuantity": 1,      	 "tranAmountExt": 200,      	 "tranAmountUnit": "US",      	 "patientLocation": "",      	 "performedBy": "Jay",      	 "enteredBy": "Jay", 	 "facility": 107,      	"accountNumber":"62580766",     	"mrn": 98765  ,    	"creditCardType":"CR-V" 	}}}



	Set token=pRequest.accessToken
	Set tStream = ""
	Set tStream = ##class(%Stream.GlobalCharacter).%New()
	Do tStream.Write(pRequest.stringObject)		
	Set tStr = tStream.Read()
	$$$TRACE("Data string: " _ tStr)	
	Do tStream.Rewind()


	Set httprequest=##class(%Net.HttpRequest).%New()

	$$$TRACE("URL: "_..Adapter.URL)
	Set tAdURL = "https://uat.sbx.ose.ihc.com" _ ..Adapter.URL, tAdURL1=$E(tAdURL)
	$$$TRACE("Location: "_tAdURL)
	Set httprequest.SSLConfiguration = ..Adapter.SSLConfig
	$$$TRACE("SSL Config: "_httprequest.SSLConfiguration)
	Set httprequest.Https="1"

	Set httprequest.ContentType="application/json"	
	do httprequest.SetHeader("apikey", "4f472d84cc2c06b89e7ed688dc304b261e8e98e798df17ea782ad04365d7449e")
	Do httprequest.EntityBody.Write()
	do httprequest.EntityBody.CopyFrom(tStream)
	set httprequest.Timeout=..Adapter.ResponseTimeout


	// set httprequest.Username = "dfduser"
	// set httprequest.Password = "dfduser"

	// set sc=##class(%SYS.OAuth2.AccessToken).AddAccessToken(httprequest,"header",..Adapter.SSLConfig,..OAuth2ClientName, token)

	set sc=##class(%SYS.OAuth2.AccessToken).AuthorizeWithAccessToken(httprequest,"header",..Adapter.SSLConfig,"PingSecurityToken",token)
	$$$TRACE("Token status (Add) "_sc)

    set status = httprequest.Post(tAdURL)

    if $$$ISERR(status) {
         do $system.OBJ.DisplayError()
         Quit status
    } else {
        set tHttpResponse=httprequest.HttpResponse
       	$$$TRACE("StatusLine: "_tHttpResponse.StatusLine)  
        $$$TRACE("StatusLine: "_tHttpResponse.Data)
       	// %Stream.GlobalCharacter
       	set stream =   tHttpResponse.Data
       	While 'stream.AtEnd 
       	{ 
       		set outStr = stream.ReadLine(,.sc,.eol)
       		$$$TRACE( outStr) 
       	}

    }        

	quit tSC
